# Builds ../sands.html (one self-contained file) and x.js (all our scripts joined, for node --check). Run from this folder.
import re, os
D = os.path.dirname(os.path.abspath(__file__))
SP = os.path.abspath(os.path.join(D, '..', '..'))   # games-src
def rd(p): return open(p, encoding='utf-8').read()
# the list of every owner picture and model, so the game can preload and use them all (generated from games/sands-of-qamar/media and models)
_G = os.path.join(SP, '..', 'games', 'sands-of-qamar')
_m = sorted(f for f in os.listdir(os.path.join(_G, 'media')) if f.endswith('.webp')) if os.path.isdir(os.path.join(_G, 'media')) else []
_g = sorted(f for f in os.listdir(os.path.join(_G, 'models')) if f.endswith('.glb')) if os.path.isdir(os.path.join(_G, 'models')) else []
open(os.path.join(D, 'assetlist.js'), 'w').write('// generated by build.py: every picture in media/ and every model in models/\nconst ASSET_FILES=' + repr(_m) + ';const ASSET_GLB=' + repr(_g) + ';\n')
h = rd(os.path.join(D, 'head.html')); b = rd(os.path.join(D, 'body.html'))
css = rd(os.path.join(D, 'board.css')) + rd(os.path.join(SP, 'shell', 'gx-skin.css')) + rd(os.path.join(D, 'skin.css')) + rd(os.path.join(SP, 'shell', 'gx-campaign.css')) + rd(os.path.join(SP, 'shell', 'gx-help.css')) + rd(os.path.join(SP, 'shell', 'gx-tutor.css'))
h = h.replace('</style>', css + '\n</style>', 1)
SRC = {'gx-scenario.js': os.path.join(SP, 'shell', 'gx-scenario.js'), 'shell.js': os.path.join(SP, 'shell', 'shell.js'), 'gx-viewport.js': os.path.join(SP, 'shell', 'gx-viewport.js'),
       'gx-campaign.js': os.path.join(SP, 'shell', 'gx-campaign.js'), 'gx-help.js': os.path.join(SP, 'shell', 'gx-help.js'), 'gx-tutor.js': os.path.join(SP, 'shell', 'gx-tutor.js'), 'gx-skin.js': os.path.join(SP, 'shell', 'gx-skin.js'), 'gameaudio.js': os.path.join(SP, 'audio', 'gameaudio.js'),
       'audio-data.js': os.path.join(SP, 'audio', 'sands', 'audio-data.js'), 'trystero.min.js': os.path.join(SP, 'net', 'trystero.min.js'),
       'netroom.js': os.path.join(SP, 'net', 'netroom.js'), 'gx-glb.js': os.path.join(SP, 'shell', 'gx-glb.js'), 'three.min.js': os.path.join(SP, 'node_modules', 'three', 'build', 'three.min.js')}
CAMP = 'window.CAMPAIGN=' + rd(os.path.join(D, '..', 'campaign.json')).strip() + ';'
ORDER = ['gx-scenario.js', 'scn.js', 'shell.js', 'gx-viewport.js', 'gx-help.js', 'gx-tutor.js', 'gx-skin.js', 'gx-campaign.js', 'campaign-data.js', 'gameaudio.js', 'audio-data.js', 'trystero.min.js', 'three.min.js', 'gx-glb.js', 'netroom.js',
         'data.js', 'djinns.js', 'engine.js', 'ai.js', 'tutdata.js', 'rules-html.js', 'story.js', 'sound.js', 'net.js', 'ui.js', 'ui2.js', 'ui3.js', 'hlp.js', 'tutor.js', 'paint.js', 'lore.js', 'playable.js', 'coach.js', 'score.js', 'assetlist.js', 'assets.js', 'models3d.js']
for f in ORDER:
    tag = f'<script src="{f}"></script>'; assert tag in b, f
    src = CAMP if f == 'campaign-data.js' else rd(SRC.get(f, os.path.join(D, f)))
    if f == 'three.min.js': src = '!' + src[src.index('),') + 2:]   # same cut the other 3D games use
    b = b.replace(tag, '<script>\n' + src.replace('</script', '<\\/script') + '\n</script>')
assert '<script src=' not in b
out = h + b
open(os.path.join(D, '..', 'sands.html'), 'w', encoding='utf-8').write(out)
big = ('gx-skin.js', 'trystero.min.js', 'gameaudio.js', 'audio-data.js', 'netroom.js', 'shell.js', 'gx-viewport.js', 'gx-help.js', 'gx-tutor.js', 'gx-campaign.js', 'campaign-data.js')
js = '\n'.join(rd(SRC.get(f, os.path.join(D, f))) if f not in ('campaign-data.js',) else CAMP for f in ORDER if f not in ('trystero.min.js', 'audio-data.js', 'three.min.js', 'gx-glb.js'))
open(os.path.join(D, 'x.js'), 'w', encoding='utf-8').write(js)
print(len(out))
